public class TimesTablePrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n") + "\"";
    }

    static String capture(int n) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            TimesTablePrinter.printGrid(n);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("printGrid(1)", "   x   1\n--------\n   1   1\n", capture(1));
        check("printGrid(3)",
                "   x   1   2   3\n----------------\n   1   1   2   3\n   2   2   4   6\n   3   3   6   9\n",
                capture(3));
        check("printGrid(0) prints nothing", "", capture(0));
        check("printGrid(-4) prints nothing", "", capture(-4));

        String six = capture(6);
        String[] lines = six.split("\n", -1);
        check("printGrid(6) line count", 8, lines.length - 1);
        check("printGrid(6) header width", 28, lines[0].length());
        check("printGrid(6) dash line", "----------------------------", lines.length > 1 ? lines[1] : "");
        check("printGrid(6) last row", "   6   6  12  18  24  30  36", lines.length > 7 ? lines[7] : "");

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

