public class TimesTablePrinter {

    public static void printGrid(int n) {
        if (n < 1) {
            return;
        }
        System.out.printf("%4s", "x");
        for (int c = 1; c <= n; c++) {
            System.out.printf("%4d", c);
        }
        System.out.println();

        for (int i = 0; i < 4 * (n + 1); i++) {
            System.out.print("-");
        }
        System.out.println();

        for (int r = 1; r <= n; r++) {
            System.out.printf("%4d", r);
            for (int c = 1; c <= n; c++) {
                System.out.printf("%4d", r * c);
            }
            System.out.println();
        }
    }
}
